          direction: {
            knob: 'select',
            defaultValue: 'vertical',
            options: ['horizontal', 'vertical'],
          },
          vertical: {
            knob: 'select',
            defaultValue: 'middle',
            options: ['top', 'middle', 'bottom'],
          },
          horizontal: {
            knob: 'select',
            defaultValue: 'center',
            options: ['start', 'center', 'end'],
